'use server'

import { createClient } from '@/lib/supabase/server'
import { revalidatePath } from 'next/cache'
import type { Database } from '@/types/database'

export type ScriptRow = Database['public']['Tables']['scripts']['Row']
export type ReelRow = Database['public']['Tables']['reels']['Row']

export interface ScriptWithReel extends ScriptRow {
  reels?: ReelRow | null
}

/**
 * Fetch all scripts generated by the authenticated user.
 */
export async function getUserScripts(options?: {
  status?: string
  language?: string
  search?: string
  scheduledOnly?: boolean
}): Promise<{ scripts: ScriptWithReel[]; error?: string }> {
  try {
    const supabase = await createClient()
    const {
      data: { user },
    } = await supabase.auth.getUser()

    if (!user) {
      return { scripts: [], error: 'Please sign in to view your scripts.' }
    }

    let query = supabase
      .from('scripts')
      .select('*')
      .eq('user_id', user.id)
      .order('created_at', { ascending: false })

    if (options?.status && options.status !== 'all') {
      query = query.eq('status', options.status as any)
    }

    if (options?.language && options.language !== 'all') {
      query = query.eq('language', options.language as any)
    }

    if (options?.scheduledOnly) {
      query = query.not('scheduled_date', 'is', null)
    }

    const { data, error } = await query

    if (error) {
      console.error('getUserScripts error:', error)
      return { scripts: [], error: error.message }
    }

    const rawScripts = (data || []) as ScriptRow[]

    // Enrich with reels data if source_reel_id exists
    const reelIds = Array.from(
      new Set(rawScripts.map((s) => s.source_reel_id).filter(Boolean))
    ) as string[]

    const reelMap = new Map<string, ReelRow>()
    if (reelIds.length > 0) {
      const { data: reelsData } = await supabase
        .from('reels')
        .select('*')
        .in('id', reelIds)
      reelsData?.forEach((r) => reelMap.set(r.id, r as ReelRow))
    }

    let scriptsWithReels: ScriptWithReel[] = rawScripts.map((s) => ({
      ...s,
      reels: s.source_reel_id ? reelMap.get(s.source_reel_id) || null : null,
    }))

    if (options?.search?.trim()) {
      const q = options.search.trim().toLowerCase()
      scriptsWithReels = scriptsWithReels.filter(
        (s) =>
          s.title?.toLowerCase().includes(q) ||
          s.hook?.toLowerCase().includes(q) ||
          s.script_body?.toLowerCase().includes(q) ||
          (Array.isArray(s.tags) &&
            (s.tags as string[]).some((t) => t.toLowerCase().includes(q)))
      )
    }

    return { scripts: scriptsWithReels }
  } catch (err: any) {
    if (err?.digest === 'DYNAMIC_SERVER_USAGE') throw err
    console.error('getUserScripts exception:', err)
    return { scripts: [], error: err.message || 'Failed to load scripts.' }
  }
}

/**
 * Fetch scripts specifically for a calendar month.
 */
export async function getCalendarScripts(
  year: number,
  month: number
): Promise<{ scripts: ScriptWithReel[]; error?: string }> {
  try {
    const supabase = await createClient()
    const {
      data: { user },
    } = await supabase.auth.getUser()

    if (!user) {
      return { scripts: [], error: 'Please sign in to view calendar.' }
    }

    // Format start and end date of target month (1-indexed month)
    const startDate = `${year}-${String(month).padStart(2, '0')}-01`
    const lastDay = new Date(year, month, 0).getDate()
    const endDate = `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`

    const { data, error } = await supabase
      .from('scripts')
      .select('*')
      .eq('user_id', user.id)
      .gte('scheduled_date', startDate)
      .lte('scheduled_date', endDate)
      .order('scheduled_date', { ascending: true })

    if (error) {
      console.error('getCalendarScripts error:', error)
      return { scripts: [], error: error.message }
    }

    const rawScripts = (data || []) as ScriptRow[]

    const reelIds = Array.from(
      new Set(rawScripts.map((s) => s.source_reel_id).filter(Boolean))
    ) as string[]

    const reelMap = new Map<string, ReelRow>()
    if (reelIds.length > 0) {
      const { data: reelsData } = await supabase
        .from('reels')
        .select('*')
        .in('id', reelIds)
      reelsData?.forEach((r) => reelMap.set(r.id, r as ReelRow))
    }

    const scriptsWithReels: ScriptWithReel[] = rawScripts.map((s) => ({
      ...s,
      reels: s.source_reel_id ? reelMap.get(s.source_reel_id) || null : null,
    }))

    return { scripts: scriptsWithReels }
  } catch (err: any) {
    console.error('getCalendarScripts exception:', err)
    return { scripts: [], error: err.message || 'Failed to load calendar scripts.' }
  }
}

/**
 * Schedule or reschedule a script to a specific calendar date (YYYY-MM-DD).
 */
export async function scheduleScript(
  scriptId: string,
  scheduledDate: string | null
): Promise<{ success: boolean; error?: string }> {
  try {
    const supabase = await createClient()
    const {
      data: { user },
    } = await supabase.auth.getUser()

    if (!user) return { success: false, error: 'Unauthorized' }

    const updatePayload: { scheduled_date: string | null } = {
      scheduled_date: scheduledDate,
    }

    const { error } = await supabase
      .from('scripts')
      .update(updatePayload)
      .eq('id', scriptId)
      .eq('user_id', user.id)

    if (error) {
      console.error('scheduleScript error:', error)
      return { success: false, error: error.message }
    }

    revalidatePath('/dashboard/calendar')
    revalidatePath('/dashboard/library')
    revalidatePath('/dashboard/studio')

    return { success: true }
  } catch (err: any) {
    console.error('scheduleScript exception:', err)
    return { success: false, error: err.message || 'Failed to schedule script.' }
  }
}

