/**
 * Create a new planned script directly from Calendar or Library.
 */
export async function createManualScript(data: {
  title: string
  hook?: string
  script_body: string
  on_screen_text?: string
  scheduled_date?: string | null
  language?: 'english' | 'hindi' | 'hinglish'
  status?: 'idea' | 'hook' | 'script' | 'filming' | 'ready' | 'posted'
}): Promise<{ script?: ScriptRow; error?: string }> {
  try {
    const supabase = await createClient()
    const {
      data: { user },
    } = await supabase.auth.getUser()

    if (!user) return { error: 'Unauthorized' }

    const { data: created, error } = await supabase
      .from('scripts')
      .insert({
        user_id: user.id,
        title: data.title.trim(),
        hook: data.hook?.trim() || null,
        script_body: data.script_body.trim() || null,
        on_screen_text: data.on_screen_text?.trim() || null,
        scheduled_date: data.scheduled_date || null,
        language: data.language || 'english',
        status: data.status || 'script',
        tags: [],
      })
      .select()
      .single()

    if (error) return { error: error.message }

    revalidatePath('/dashboard/calendar')
    revalidatePath('/dashboard/library')

    return { script: created }
  } catch (err: any) {
    return { error: err.message || 'Failed to create script.' }
  }
}

export interface SearchedReelItem {
  url: string
  reel_id?: string | null
  creator_handle?: string | null
  creator_name?: string | null
  creator_profile_pic?: string | null
  caption?: string | null
  view_count?: number
  like_count?: number
  comment_count?: number
  audio_name?: string | null
  last_used_at?: string
  scripts_count: number
}

/**
 * Fetch all unique Instagram reels searched or analyzed by the creator.
 */
export async function getUserSearchedReels(): Promise<{
  reels: SearchedReelItem[]
  error?: string
}> {
  try {
    const supabase = await createClient()
    const {
      data: { user },
    } = await supabase.auth.getUser()

    if (!user) return { reels: [], error: 'Unauthorized' }

    // 1. Fetch user's scripts that have source_url or source_reel_id
    const { data: userScripts, error } = await supabase
      .from('scripts')
      .select('*')
      .eq('user_id', user.id)
      .not('source_url', 'is', null)
      .order('created_at', { ascending: false })

    if (error) {
      console.error('getUserSearchedReels error:', error)
      return { reels: [], error: error.message }
    }

    const scriptsList = (userScripts || []) as ScriptRow[]

    // Fetch related reel rows
    const reelIds = Array.from(
      new Set(scriptsList.map((s) => s.source_reel_id).filter(Boolean))
    ) as string[]

    const reelMap = new Map<string, ReelRow>()
    if (reelIds.length > 0) {
      const { data: reelsData } = await supabase
        .from('reels')
        .select('*')
        .in('id', reelIds)
      reelsData?.forEach((r) => reelMap.set(r.id, r as ReelRow))
    }

    // Map unique reel URLs
    const itemsMap = new Map<string, SearchedReelItem>()

    for (const item of scriptsList) {
      if (!item.source_url) continue
      const url = item.source_url
      const reel = item.source_reel_id ? reelMap.get(item.source_reel_id) : null

      if (!itemsMap.has(url)) {
        itemsMap.set(url, {
          url,
          reel_id: item.source_reel_id,
          creator_handle: reel?.creator_handle || 'creator',
          creator_name: reel?.creator_name || null,
          creator_profile_pic: reel?.creator_profile_pic || null,
          caption: reel?.caption || null,
          view_count: reel?.view_count || 0,
          like_count: reel?.like_count || 0,
          comment_count: reel?.comment_count || 0,
          audio_name: reel?.audio_name || null,
          last_used_at: item.created_at,
          scripts_count: 1,
        })
      } else {
        const existing = itemsMap.get(url)!
        existing.scripts_count += 1
      }
    }

    return { reels: Array.from(itemsMap.values()) }
  } catch (err: any) {
    if (err?.digest === 'DYNAMIC_SERVER_USAGE') throw err
    console.error('getUserSearchedReels exception:', err)
    return { reels: [], error: err.message || 'Failed to fetch searched reels.' }
  }
}
